import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
const path = name => fileURLToPath(new URL(name,import.meta.url));
const variant = process.argv[2];
for(const driver of ['deepbench','lookupbench']){
 const source = readFileSync(path(variant+'-'+driver+'.js'),'utf8');
 const record = /function _M0TP210JingLan0v03stn13ScheduledTask\([^\n]*\) \{/;
 const conflict = '_M0FP210JingLan0v03stn25first__resource__conflict';
 assert(record.test(source) && source.includes('function '+conflict+'('));
 const header = `const stats = {nodes:0, taskRecords:0, conflictMs:0, scheduleMs:0, builds:0};
const savedConflict = ${conflict};
${conflict} = (...args) => {
  stats.nodes++;
  const started = performance.now();
  try { return savedConflict(...args); }
  finally { stats.conflictMs += performance.now() - started; }
};
process.once('exit', () => console.error(JSON.stringify(stats)));\n`;
 let body = source.replace(record,'$&\n  stats.taskRecords++;');
 if(variant === 'base'){
  const alloc = /^( +)let schedule;$/m;
  const call = /^( +)const [^\n]*= _M0FP210JingLan0v03stn25first__resource__conflict\(p\.tasks, schedule\);$/m;
  assert(alloc.test(body) && call.test(body));
  body = body.replace(alloc,'$1const scheduleStarted = performance.now();\n$&')
    .replace(call,'$1stats.builds++; stats.scheduleMs += performance.now() - scheduleStarted;\n$&');
 }
 writeFileSync(path(variant+'-'+driver+'-probe.js'),header+body);
}
const rows = ['tight-impossible','maintenance','max-model','max-root'].map(name => {
 const args = name==='tight-impossible'?[path(variant+'-deepbench-probe.js')]:[path(variant+'-lookupbench-probe.js'),name];
 const samples=Array.from({length:3},()=>{
  const result = spawnSync(process.execPath,args,{encoding:'utf8',timeout:40000});
  assert.equal(result.status,0,result.stderr);
  assert.equal(result.stdout.trim().split(/\r?\n/).length,9);
  return JSON.parse(result.stderr);
 });
 return {name,samples};
});
writeFileSync(path(variant+'-probe.json'),JSON.stringify(rows,null,2)+'\n');
console.log(JSON.stringify(rows));

